<?php if(!defined('ABSPATH'))exit;$plans=woogit_plans();get_header();?><section class="wg-section"><div class="wg-container"><div class="wg-section-head"><span class="wg-eyebrow">قیمت‌گذاری</span><h1>پلن مناسب WooGit را انتخاب کنید</h1><p>قیمت و شرایط از Backend/WooCommerce رسمی WooGit دریافت می‌شود.</p></div><div class="wg-grid wg-grid--3"><?php if(!$plans): ?><div class="wg-card wg-empty"><h2>قیمت‌گذاری موقتاً در دسترس نیست.</h2><p>لطفاً بعداً دوباره تلاش کنید.</p></div><?php else: foreach($plans as $plan): if(!is_array($plan))continue;$id=(int)($plan['id']??$plan['plan_id']??0);$featured=!empty($plan['featured'])||!empty($plan['popular'])||!empty($plan['is_featured']);$trial=(int)($plan['trial_days']??0);$variations=(array)($plan['variations']??[]);?><article class="wg-plan<?php echo $featured?' wg-plan--featured':''; ?>"><?php if($featured): ?><span class="wg-plan__badge">پیشنهاد اصلی</span><?php endif; ?><h2><?php echo woogit_safe_text($plan['name']??'پلن'); ?></h2><div class="wg-price"><?php echo woogit_safe_text($plan['price']??'—'); ?> <small><?php echo woogit_safe_text($plan['currency']??''); ?></small></div><?php if($trial>0): ?><span class="wg-plan__trial"><?php echo esc_html($trial); ?> روز آزمایشی</span><?php endif; ?><p><?php echo woogit_safe_text($plan['description']??''); ?></p><?php if($variations): ?><label>نوع پلن<select data-woogit-variation-select data-plan-id="<?php echo esc_attr($id); ?>"><option value="">انتخاب کنید</option><?php foreach($variations as $v): if(!is_array($v))continue;$vid=(int)($v['id']??$v['variation_id']??0); ?><option value="<?php echo esc_attr($vid); ?>"><?php echo woogit_safe_text($v['name']??$v['title']??$v['label']??'گزینه'); ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="wg-btn" type="button" data-woogit-checkout data-plan-id="<?php echo esc_attr($id); ?>" data-variation-id="0"><?php echo $trial>0?'شروع آزمایشی':'ادامه به پرداخت'; ?></button><p class="wg-form-message" data-woogit-checkout-message aria-live="polite"></p></article><?php endforeach;endif; ?></div></div></section><?php get_footer(); ?>